-- 01_estructura.sql  (GENERADO por generar_datos_prueba.py; no editar a mano)
USE [gestionasistenciadb];
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
SET NOCOUNT ON;
SET XACT_ABORT ON;

IF EXISTS (SELECT 1 FROM dbo.Sesion WHERE grupo <> 'A1B2C3D4-E5F6-7A8B-9C0D-1E2F3A4B5C6D')
    OR (SELECT COUNT(*) FROM dbo.Usuario) > 80
    THROW 50001, N'La base no parece recien desplegada: los datos de prueba se cargan sobre deploy_schema limpio.', 1;

BEGIN TRANSACTION;

-- Catalogos por codigo
DECLARE @tiCC UNIQUEIDENTIFIER = (SELECT id FROM dbo.TipoIdentificacion WHERE tipoIdentificacion = 'CC');
DECLARE @egA UNIQUEIDENTIFIER = (SELECT id FROM dbo.EstadoEstudianteGrupo WHERE codigo = 'A');

-- Limpieza de la demo de las semillas (sesiones y matriculas del grupo ARQ; segundo administrador)
DECLARE @gArq UNIQUEIDENTIFIER = 'A1B2C3D4-E5F6-7A8B-9C0D-1E2F3A4B5C6D';
DELETE da FROM dbo.DetalleAsistencia da JOIN dbo.Asistencia a ON a.id = da.asistencia JOIN dbo.Sesion s ON s.id = a.sesion WHERE s.grupo = @gArq;
DELETE a FROM dbo.Asistencia a JOIN dbo.Sesion s ON s.id = a.sesion WHERE s.grupo = @gArq;
DELETE t FROM dbo.TokenAsistenciaToma t JOIN dbo.TomaAsistencia ta ON ta.id = t.toma JOIN dbo.Sesion s ON s.id = ta.sesion WHERE s.grupo = @gArq;
DELETE ta FROM dbo.TomaAsistencia ta JOIN dbo.Sesion s ON s.id = ta.sesion WHERE s.grupo = @gArq;
DELETE sc FROM dbo.SesionCancelacion sc JOIN dbo.Sesion s ON s.id = sc.sesion WHERE s.grupo = @gArq;
DELETE ss FROM dbo.SesionSolicitud ss JOIN dbo.Sesion s ON s.id = ss.sesion WHERE s.grupo = @gArq;
DELETE af FROM dbo.AvisoFaltaSesion af JOIN dbo.Sesion s ON s.id = af.sesion WHERE s.grupo = @gArq;
DELETE FROM dbo.Sesion WHERE grupo = @gArq;
DELETE FROM dbo.Horario WHERE grupo = @gArq;
DELETE FROM dbo.EstudianteGrupo WHERE grupo = @gArq;
DELETE FROM dbo.Administrador WHERE id = 'F1A2B3C4-0000-0000-0000-000000000006';
DELETE FROM dbo.Usuario WHERE id = 'E1F2A3B4-0000-0000-0000-000000000006'
  AND NOT EXISTS (SELECT 1 FROM dbo.Administrador WHERE usuario = 'E1F2A3B4-0000-0000-0000-000000000006');

